package com.kaymlyn.planeteater.celestial;

import com.kaymlyn.planeteater.resources.Composition;
import com.kaymlyn.planeteater.resources.Material;
import com.kaymlyn.planeteater.physics.Vector3D;
import lombok.Getter;

/**
 * Represents a planet with differentiated layers
 * Unlike asteroids, planets have distinct core, mantle, and crust/atmosphere
 * 
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
public class Planet extends CelestialBody {
    
    public enum PlanetType {
        TERRESTRIAL,  // Rocky planets like Earth, Mars
        GAS_GIANT,    // Jupiter, Saturn
        ICE_GIANT     // Uranus, Neptune
    }
    
    private PlanetType type;
    private Composition coreComposition;
    private Composition mantleComposition;
    private Composition crustComposition;
    private Composition atmosphereComposition;
    
    public Planet(String id, Vector3D position, Vector3D velocity, PlanetType type) {
        super(id, position, velocity, new Composition());
        this.type = type;
        this.coreComposition = new Composition();
        this.mantleComposition = new Composition();
        this.crustComposition = new Composition();
        this.atmosphereComposition = new Composition();
    }
    
    /**
     * Override to calculate total mass from all layers
     */
    @Override
    public double getMass() {
        return coreComposition.getTotalMass() + 
               mantleComposition.getTotalMass() + 
               crustComposition.getTotalMass() + 
               atmosphereComposition.getTotalMass();
    }
    
    /**
     * For planets, radius should be set explicitly based on layer volumes
     */
    @Override
    public double getRadius() {
        // Sum volumes of all layers and calculate radius
        double totalVolume = coreComposition.getTotalVolume() + 
                           mantleComposition.getTotalVolume() + 
                           crustComposition.getTotalVolume() + 
                           atmosphereComposition.getTotalVolume();
        return Math.cbrt((3.0 * totalVolume) / (4.0 * Math.PI));
    }
    
    /**
     * Create an Earth-like terrestrial planet
     * com.kaymlyn.planeteater.entites.system.Composition by mass: ~32% Fe, ~30% O, ~15% Si, ~14% Mg, ~3% S, ~2% Ni, ~1.5% Ca, ~1.4% Al
     */
    public static Planet createEarthLike(String id, Vector3D position, Vector3D velocity) {
        Planet planet = new Planet(id, position, velocity, PlanetType.TERRESTRIAL);
        
        // Core: Iron-nickel with sulfur (radius ~3480 km, ~32% of Earth's mass)
        double coreVolume = (4.0 / 3.0) * Math.PI * Math.pow(3.48e6, 3);
        planet.coreComposition.addMaterial(Material.IRON, Material.IRON.massForVolume(coreVolume * 0.85));
        planet.coreComposition.addMaterial(Material.NICKEL, Material.NICKEL.massForVolume(coreVolume * 0.10));
        planet.coreComposition.addMaterial(Material.IRON_SULFIDE, Material.IRON_SULFIDE.massForVolume(coreVolume * 0.05));
        
        // Mantle: Silicates dominated (radius ~6370 km from core, ~68% of mass)
        double mantleVolume = (4.0 / 3.0) * Math.PI * 
            (Math.pow(6.37e6, 3) - Math.pow(3.48e6, 3));
        planet.mantleComposition.addMaterial(Material.OLIVINE, Material.OLIVINE.massForVolume(mantleVolume * 0.50));
        planet.mantleComposition.addMaterial(Material.PYROXENE, Material.PYROXENE.massForVolume(mantleVolume * 0.25));
        planet.mantleComposition.addMaterial(Material.MAGNESIUM_OXIDE, Material.MAGNESIUM_OXIDE.massForVolume(mantleVolume * 0.15));
        planet.mantleComposition.addMaterial(Material.IRON_OXIDE, Material.IRON_OXIDE.massForVolume(mantleVolume * 0.10));
        
        // Crust: Silicates, feldspars, various minerals (~0.4% of mass)
        double crustVolume = (4.0 / 3.0) * Math.PI * 
            (Math.pow(6.371e6, 3) - Math.pow(6.37e6, 3));
        planet.crustComposition.addMaterial(Material.FELDSPAR, Material.FELDSPAR.massForVolume(crustVolume * 0.40));
        planet.crustComposition.addMaterial(Material.SILICA, Material.SILICA.massForVolume(crustVolume * 0.30));
        planet.crustComposition.addMaterial(Material.PYROXENE, Material.PYROXENE.massForVolume(crustVolume * 0.10));
        planet.crustComposition.addMaterial(Material.ALUMINUM_OXIDE, Material.ALUMINUM_OXIDE.massForVolume(crustVolume * 0.10));
        planet.crustComposition.addMaterial(Material.CALCIUM_OXIDE, Material.CALCIUM_OXIDE.massForVolume(crustVolume * 0.05));
        planet.crustComposition.addMaterial(Material.IRON_OXIDE, Material.IRON_OXIDE.massForVolume(crustVolume * 0.05));
        
        // Atmosphere and hydrosphere: Water, nitrogen, oxygen (negligible mass ~0.0001%)
        planet.atmosphereComposition.addMaterial(Material.WATER_ICE, 1.4e21); // Oceans
        planet.atmosphereComposition.addMaterial(Material.NITROGEN_GAS, 4.0e18); // Atmosphere N₂
        planet.atmosphereComposition.addMaterial(Material.OXYGEN_GAS, 1.2e18); // Atmosphere O₂
        planet.atmosphereComposition.addMaterial(Material.CO2_ICE, 3.0e15); // Trace CO₂
        
        return planet;
    }
    
    /**
     * Create a Jupiter-like gas giant
     * Jupiter composition: ~71% H, ~24% He, ~5% heavier elements
     */
    public static Planet createJupiterLike(String id, Vector3D position, Vector3D velocity) {
        Planet planet = new Planet(id, position, velocity, PlanetType.GAS_GIANT);
        
        // Core: Rock and ice (radius ~10,000 km)
        double coreVolume = (4.0 / 3.0) * Math.PI * Math.pow(1.0e7, 3);
        planet.coreComposition.addMaterial(Material.SILICA, Material.SILICA.massForVolume(coreVolume * 0.40));
        planet.coreComposition.addMaterial(Material.IRON, Material.IRON.massForVolume(coreVolume * 0.30));
        planet.coreComposition.addMaterial(Material.WATER_ICE, Material.WATER_ICE.massForVolume(coreVolume * 0.20));
        planet.coreComposition.addMaterial(Material.MAGNESIUM_OXIDE, Material.MAGNESIUM_OXIDE.massForVolume(coreVolume * 0.10));
        
        // Atmosphere: Hydrogen and helium dominated
        double atmosphereVolume = (4.0 / 3.0) * Math.PI * 
            (Math.pow(7.0e7, 3) - Math.pow(1.0e7, 3));
        planet.atmosphereComposition.addMaterial(Material.HYDROGEN, Material.HYDROGEN.massForVolume(atmosphereVolume * 0.71));
        planet.atmosphereComposition.addMaterial(Material.HELIUM, Material.HELIUM.massForVolume(atmosphereVolume * 0.24));
        planet.atmosphereComposition.addMaterial(Material.METHANE_ICE, Material.METHANE_ICE.massForVolume(atmosphereVolume * 0.03));
        planet.atmosphereComposition.addMaterial(Material.AMMONIA_ICE, Material.AMMONIA_ICE.massForVolume(atmosphereVolume * 0.02));
        
        return planet;
    }
    
    /**
     * Create a Neptune-like ice giant
     * com.kaymlyn.planeteater.entites.system.Composition: ~20% H/He, ~60-70% ices, ~10-20% rock/metal
     */
    public static Planet createNeptuneLike(String id, Vector3D position, Vector3D velocity) {
        Planet planet = new Planet(id, position, velocity, PlanetType.ICE_GIANT);
        
        // Core: Rock and metal (radius ~8,000 km)
        double coreVolume = (4.0 / 3.0) * Math.PI * Math.pow(8.0e6, 3);
        planet.coreComposition.addMaterial(Material.SILICA, Material.SILICA.massForVolume(coreVolume * 0.50));
        planet.coreComposition.addMaterial(Material.IRON, Material.IRON.massForVolume(coreVolume * 0.30));
        planet.coreComposition.addMaterial(Material.MAGNESIUM_OXIDE, Material.MAGNESIUM_OXIDE.massForVolume(coreVolume * 0.20));
        
        // Mantle: Ices (water, ammonia, methane)
        double mantleVolume = (4.0 / 3.0) * Math.PI * 
            (Math.pow(2.0e7, 3) - Math.pow(8.0e6, 3));
        planet.mantleComposition.addMaterial(Material.WATER_ICE, Material.WATER_ICE.massForVolume(mantleVolume * 0.55));
        planet.mantleComposition.addMaterial(Material.AMMONIA_ICE, Material.AMMONIA_ICE.massForVolume(mantleVolume * 0.25));
        planet.mantleComposition.addMaterial(Material.METHANE_ICE, Material.METHANE_ICE.massForVolume(mantleVolume * 0.20));
        
        // Atmosphere: Hydrogen, helium, methane
        double atmosphereVolume = (4.0 / 3.0) * Math.PI * 
            (Math.pow(2.46e7, 3) - Math.pow(2.0e7, 3));
        planet.atmosphereComposition.addMaterial(Material.HYDROGEN, Material.HYDROGEN.massForVolume(atmosphereVolume * 0.80));
        planet.atmosphereComposition.addMaterial(Material.HELIUM, Material.HELIUM.massForVolume(atmosphereVolume * 0.15));
        planet.atmosphereComposition.addMaterial(Material.METHANE_ICE, Material.METHANE_ICE.massForVolume(atmosphereVolume * 0.05));
        
        return planet;
    }
    
    /**
     * For planets, only the crust and atmosphere are accessible for mining
     * Deep mining could theoretically access mantle materials
     */
    public boolean canMine() {
        return type == PlanetType.TERRESTRIAL; // Can't mine gas/ice giants in any practical way
    }
    
    /**
     * Mine from the crust (surface mining)
     */
    public double mineCrustMaterial(Material material, double requestedMass) {
        if (!canMine()) {
            return 0.0;
        }
        return crustComposition.removeMaterial(material, requestedMass);
    }
    
    /**
     * Extract from atmosphere (gas harvesting)
     */
    public double harvestAtmosphere(Material material, double requestedMass) {
        return atmosphereComposition.removeMaterial(material, requestedMass);
    }
    
    @Override
    public String toString() {
        return String.format("com.kaymlyn.planeteater.entites.system.Planet[id=%s, type=%s, pos=%s, mass=%.3e kg, radius=%.3e m]",
            id, type, position, getMass(), getRadius());
    }
}